//! 🖼️ Frame membership reads original graph rows with sealed source bindings and bounded key scans.
use crate::LayoutMutation;
use super::super::simple::SimpleAdvance;
use super::super::target::{LayoutTargetLookup,LayoutTargetSource};
use semio_s_artifact_layout_layout_model::{snapshot::LayoutSnapshot,Frame,Page,ParentPage,Layer,TextStory,ImageLink};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneBinding,RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original Layout frame membership source is invalid")}
fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=256;d.depth+=1;d}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.saturating_sub(256),maximum_depth:g.maximum_depth.saturating_sub(1),..g}}
fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_bytes+=256;p.copied_items=p.copied_items.max(1);p}
fn refused(e:ValueError)->ValueError{let p=receipt(e.retained_progress());e.with_retained_progress(p)}
fn page_id(m:&LayoutMutation)->&str{match m{LayoutMutation::CreateFrame(p)=>&p.page_id,LayoutMutation::DeleteFrame(p)=>&p.page_id,_=>unreachable!("frame membership kind")}}
fn frame_id(m:&LayoutMutation)->&str{match m{LayoutMutation::CreateFrame(p)=>p.frame.id(),LayoutMutation::DeleteFrame(p)=>&p.frame_id,_=>unreachable!("frame membership kind")}}
fn envelope(frame:&Frame)->bool{if semio_s_artifact_layout_layout_model::validation::validate_frame_bounds(frame.bounds()).is_err(){return false}match frame{Frame::Rect{fill,stroke,..}=>fill.as_ref().is_none_or(|c|c.iter().all(|v|v.is_finite()))&&stroke.as_ref().is_none_or(|c|c.iter().all(|v|v.is_finite())),Frame::Text{columns,inset,..}=>*columns>0&&[inset.x,inset.y,inset.width,inset.height].iter().all(|v|v.is_finite())&&inset.width>=0.0&&inset.height>=0.0,_=>true}}
enum Rows<'a>{Pages(&'a[Page]),Parents(&'a[ParentPage]),Frames(&'a[Frame]),Layers(&'a[Layer]),Stories(&'a[TextStory]),Links(&'a[ImageLink]),Incoming(&'a[Frame],Option<usize>)}
impl LayoutTargetSource for Rows<'_>{fn identity(&self)->usize{match self{Self::Pages(_)=>0,Self::Parents(_)=>1,Self::Frames(_)=>2,Self::Layers(_)=>3,Self::Stories(_)=>4,Self::Links(_)=>5,Self::Incoming(_,_)=>6}}fn count(&self)->usize{match self{Self::Pages(rows)=>rows.len(),Self::Parents(rows)=>rows.len(),Self::Frames(rows)|Self::Incoming(rows,_)=>rows.len(),Self::Layers(rows)=>rows.len(),Self::Stories(rows)=>rows.len(),Self::Links(rows)=>rows.len()}}fn key(&self,i:usize)->&str{match self{Self::Pages(rows)=>&rows[i].id,Self::Parents(rows)=>&rows[i].id,Self::Frames(rows)=>rows[i].id(),Self::Layers(rows)=>&rows[i].id,Self::Stories(rows)=>&rows[i].id,Self::Links(rows)=>&rows[i].id,Self::Incoming(rows,skip)=>if *skip==Some(i){""}else{match &rows[i]{Frame::Text{thread_next:Some(id),..}=>id,_=>""}}}}}
/// 🧳 Only original source aliases and numeric target/thread coordinates survive between turns.
pub struct FrameDecision{m:Option<RetainedCloneBinding>,b:Option<RetainedCloneBinding>,cursor:LayoutTargetLookup,pub at:[usize;2],next:[usize;2],parent:usize,page:usize,phase:u8,offset:usize,error:Option<&'static str>,closing:bool}
impl Default for FrameDecision{fn default()->Self{Self{m:None,b:None,cursor:Default::default(),at:[0;2],next:[0;2],parent:0,page:0,phase:2,offset:0,error:None,closing:false}}}
impl FrameDecision{
 pub fn demand(&self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,_body:usize)->Result<RetirementDemand,ValueError>{if self.closing||!matches!(m.get(),LayoutMutation::CreateFrame(_)|LayoutMutation::DeleteFrame(_)){return Err(fault())}let md=m.binding_demand(&self.m)?;let bd=b.binding_demand(&self.b)?;Ok(if self.m.is_none(){nested(md.unwrap_or_default())}else if self.b.is_none(){nested(bd.unwrap_or_default())}else if self.phase==15{Default::default()}else{RetirementDemand{copy_bytes:1024,depth:1,..Default::default()}})}
 fn go(&mut self,phase:u8){self.cursor=Default::default();self.phase=phase;self.offset=0}
 fn lookup(&mut self,rows:&impl LayoutTargetSource,target:&str,g:RetainedCloneGrant,out:&mut SimpleAdvance)->Result<Option<Option<usize>>,ValueError>{let step=self.cursor.advance(rows,self.phase as usize,target,RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.saturating_sub(256),..g})?;out.progress=receipt(step.progress());Ok(self.cursor.result())}
 pub fn advance(&mut self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,g:RetainedCloneGrant)->Result<SimpleAdvance,ValueError>{let d=self.demand(m,b,g.maximum_copy_bytes)?;let mut out=SimpleAdvance{progress:Default::default(),done:self.phase==15,unchanged:false,error:self.error};if self.phase==15||!retained_clone_grant_admits(g,d){return Ok(out)}if self.m.is_none(){out.progress=receipt(m.bind(&mut self.m,child(g)).map_err(refused)?.unwrap_or_default());return Ok(out)}if self.b.is_none(){out.progress=receipt(b.bind(&mut self.b,child(g)).map_err(refused)?.unwrap_or_default());return Ok(out)}out.progress=RetainedCloneProgress{copied_items:1,copied_bytes:1024,..Default::default()};let(m,b)=(m.get(),b.get());let create=matches!(m,LayoutMutation::CreateFrame(_));match self.phase{
 2=>if let Some(found)=self.lookup(&Rows::Pages(&b.pages),page_id(m),g,&mut out)?{if let Some(page)=found{self.at[0]=page;self.go(3)}else{out.error=Some("mutation.target-missing")}},
 3=>if let Some(found)=self.lookup(&Rows::Frames(&b.pages[self.at[0]].frames),frame_id(m),g,&mut out)?{if create{if found.is_some(){out.error=Some("mutation.duplicate-id")}else{self.go(4)}}else if let Some(frame)=found{self.at[1]=frame;self.page=0;self.go(14)}else{out.error=Some("mutation.target-missing")}},
 4=>{let LayoutMutation::CreateFrame(p)=m else{return Err(fault())};if p.index.is_some_and(|i|i>b.pages[self.at[0]].frames.len()){out.error=Some("mutation.target-missing")}else{self.go(5)}},
 5=>{let id=frame_id(m);let mut used=0;let mut nonwhite=false;for c in id[self.offset..].chars().take(64){used+=c.len_utf8();nonwhite|=!c.is_whitespace()}self.offset+=used;if nonwhite{self.page=0;self.go(6)}else if self.offset==id.len(){out.error=Some("mutation.invariant")}},
 6=>if self.page==b.pages.len(){self.go(7)}else if self.page==self.at[0]{self.page+=1}else if let Some(found)=self.lookup(&Rows::Frames(&b.pages[self.page].frames),frame_id(m),g,&mut out)?{if found.is_some(){out.error=Some("mutation.invariant")}else{self.page+=1;self.go(6)}},
 7=>if let Some(id)=b.pages[self.at[0]].parent_page_id.as_deref(){if let Some(found)=self.lookup(&Rows::Parents(&b.parent_pages),id,g,&mut out)?{if let Some(parent)=found{self.parent=parent;self.go(8)}else{out.error=Some("mutation.invariant")}}}else{self.go(9)},
 8=>if let Some(found)=self.lookup(&Rows::Frames(&b.parent_pages[self.parent].frames),frame_id(m),g,&mut out)?{if found.is_some(){out.error=Some("mutation.invariant")}else{self.go(9)}},
 9=>{let LayoutMutation::CreateFrame(p)=m else{return Err(fault())};if envelope(&p.frame){self.go(10)}else{out.error=Some("mutation.invariant")}},
 10=>{let LayoutMutation::CreateFrame(p)=m else{return Err(fault())};if let Some(found)=self.lookup(&Rows::Layers(&b.pages[self.at[0]].layers),p.layer_id.as_deref().unwrap_or_else(||p.frame.layer_id()),g,&mut out)?{if found.is_some(){self.go(11)}else{out.error=Some("mutation.invariant")}}},
 11=>{let LayoutMutation::CreateFrame(p)=m else{return Err(fault())};match &p.frame{Frame::Rect{..}=>self.go(15),Frame::Text{story_id,..}=>if let Some(found)=self.lookup(&Rows::Stories(&b.stories),story_id,g,&mut out)?{if found.is_some(){self.page=0;self.go(12)}else{out.error=Some("mutation.invariant")}},Frame::Image{link_id,..}=>if let Some(found)=self.lookup(&Rows::Links(&b.links),link_id,g,&mut out)?{if found.is_some(){self.go(15)}else{out.error=Some("mutation.invariant")}}}},
 12=>{let LayoutMutation::CreateFrame(p)=m else{return Err(fault())};let Frame::Text{thread_next,..}=&p.frame else{return Err(fault())};if let Some(next)=thread_next{if self.page==b.pages.len(){out.error=Some("mutation.invariant")}else if let Some(found)=self.lookup(&Rows::Frames(&b.pages[self.page].frames),next,g,&mut out)?{if let Some(frame)=found{self.next=[self.page,frame];self.go(13)}else{self.page+=1;self.go(12)}}}else{self.go(15)}},
 13=>{let LayoutMutation::CreateFrame(p)=m else{return Err(fault())};let Frame::Text{story_id,..}=&p.frame else{return Err(fault())};if let Frame::Text{story_id:held,..}=&b.pages[self.next[0]].frames[self.next[1]]{if story_id.len()!=held.len(){out.error=Some("mutation.invariant")}else{let end=story_id.len().min(self.offset+256);if story_id.as_bytes()[self.offset..end]!=held.as_bytes()[self.offset..end]{out.error=Some("mutation.invariant")}else if end==story_id.len(){self.page=0;self.go(14)}else{self.offset=end}}}else{out.error=Some("mutation.invariant")}},
 14=>if self.page==b.pages.len(){self.go(15)}else{let target=if create{let LayoutMutation::CreateFrame(p)=m else{return Err(fault())};let Frame::Text{thread_next:Some(next),..}=&p.frame else{return Err(fault())};next.as_str()}else{frame_id(m)};let skip=(!create&&self.page==self.at[0]).then_some(self.at[1]);if let Some(found)=self.lookup(&Rows::Incoming(&b.pages[self.page].frames,skip),target,g,&mut out)?{if found.is_some(){out.error=Some("mutation.invariant")}else{self.page+=1;self.go(14)}}},
 _=>return Err(fault())}if out.error.is_some(){self.error=out.error;self.phase=15}out.done=self.phase==15;Ok(out)}
 pub fn begin_close(&mut self){self.closing=true;self.cursor.begin_close()}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.cursor.terminal_is_empty(){return Ok(nested(self.cursor.close_demand()))}if self.m.is_some(){return Ok(nested(RetainedCloneBinding::close_demand(&self.m,body.saturating_sub(256))?))}Ok(nested(RetainedCloneBinding::close_demand(&self.b,body.saturating_sub(256))?))}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(fault())}let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.cursor.terminal_is_empty(){return Ok(RetainedCloneStep::Progress(receipt(self.cursor.close_step(child(g)).progress())))}let p=if self.m.is_some(){receipt(RetainedCloneBinding::close_one(&mut self.m,child(g)).map_err(refused)?.progress())}else{receipt(RetainedCloneBinding::close_one(&mut self.b,child(g)).map_err(refused)?.progress())};Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.m.is_none()&&self.b.is_none()&&self.cursor.terminal_is_empty()}}
impl Drop for FrameDecision{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"frame membership decision needs original alias closure")}}
